"""CityMind - Predictive Intelligence API Router."""

from typing import List
from fastapi import APIRouter, Query
from city_mind.models.prediction import PredictiveAlert, DomainForecast, ForecastHorizon
from city_mind.predictions.forecast_engine import forecast_engine


router = APIRouter(prefix="/api/v1/predictions", tags=["Predictive Intelligence"])


@router.get("/alerts", response_model=List[PredictiveAlert])
async def get_predictive_alerts():
    """Retrieve predictive alerts generated by time-series forecasting models."""
    return forecast_engine.generate_alerts()


@router.get("/forecast", response_model=DomainForecast)
async def get_forecast(
    domain: str = Query(default="environment", description="traffic, environment, infrastructure"),
    zone_id: str = Query(default="zone-west"),
    horizon: ForecastHorizon = Query(default=ForecastHorizon.FOUR_HOURS)
):
    """Get time-series metric forecast with confidence intervals."""
    return forecast_engine.get_domain_forecast(domain=domain, zone_id=zone_id, horizon=horizon)
